// Synthetic daily series for tests (no network). Outside the *.test.ts glob:
// node --test does not run it as a suite.
import type { HistoricalBar } from "../../providers/types.js";

/** Bars on consecutive weekdays from `start` (skipping Saturdays and Sundays); high = low = close. */
export function weekdayBars(start: string, closes: number[]): HistoricalBar[] {
  const d = new Date(`${start}T00:00:00Z`);
  return closes.map((close) => {
    while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d.setUTCDate(d.getUTCDate() + 1);
    const bar = { date: d.toISOString().slice(0, 10), close, high: close, low: close };
    d.setUTCDate(d.getUTCDate() + 1);
    return bar;
  });
}

/** `n` closes generated by `closeAt(i)`, for long series. */
export function closes(n: number, closeAt: (i: number) => number): number[] {
  return Array.from({ length: n }, (_, i) => closeAt(i));
}
